INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPFBQ', '04', 'SQL', 'SELECT
    case when REP_OPEN_CIRCLE = ''06'' then 0.5
     when REP_OPEN_CIRCLE = ''07'' then 1
     when REP_OPEN_CIRCLE = ''99'' and round(REP_OPEN_CIRCLE_DAYS/365, 2) >= 0.5 then round(REP_OPEN_CIRCLE_DAYS/365, 2)
     else 0
    end as RVALUE
FROM
    REP_PROD_ISSUE
WHERE
        REP_FINPROD_ID = (select max(FINPROD_ID) from FIN_PRODUCT_ADD where PORTFOLIO_ID in ${portfolioCode})
    and REP_OPEN_CIRCLE in (''06'', ''07'', ''99'')', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
