INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPJZCJZ', '02', 'SQL', 'WITH  temp  as(			
  SELECT 			
       DISTINCT t2.PORTFOLIO_ID ,			
       mujiData.mujiAmt  as AMOUNT			
       from  PTL_PORTFOLIO t2			
       left join 			
       (			
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1			
       WHERE  t1.PS in (''C1'', ''C2'')	 and t1.SETTLE_DATE <= date''${valDate}'' and t1.TRADE_STATUS=''01''		
       group by t1.PORTFOLIO_ID			
       ) mujiData			
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID			
       where  t2.VDATE=date''${valDate}''			
 UNION ALL			
      SELECT 			
       DISTINCT t1.PORTFOLIO_ID RKEY,			
        nvl(TDY_ASSET_NETVALUE,0) as RVALUE			
       from PTL_PORTFOLIO_VALUATION t1			
       where  t1.CDATE=date''${valDate}''-1 			
 )			
 SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp			
union all			
   select m.PTL_BAG_ID as RKEY,		 	
   (		 	
        SELECT sum(AMOUNT) FROM ( 			
          SELECT PORTFOLIO_ID,AMOUNT FROM temp			
	   	 ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1	 
	     inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)		
   ) AS RVALUE		 	
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('ZHKTZZCXZ', '02', 'SQL', 'select VALUE AS RVALUE,TYPENAME AS RKEY from (with tmp as (select 												
case when ${assetType}=''F01'' then ''PINAN_ASSET_TYPE,WINDTYPEONE,WINDTYPETWO''												
when  ${assetType}=''F02'' then ''PINAN_ASSET_TYPE,FUND_ASSET_TYPE,FUND_ASSET_SECOND_TYPE''												 
when  ${assetType}=''F06'' then ''PINAN_ASSET_TYPE,ASSET_TYPE_PROJECT,ASSET_TYPE_PROJECT_TWO''												
when  ${assetType}=''F05'' then ''PINAN_ASSET_TYPE,DEPO_ASSET_TYPE,DEPO_TYPE''												
else ''PINAN_ASSET_TYPE'' end ITEMCODE												
from dual)												
SELECT m.VALUE,n.ITEM_VALUE as TYPENAME FROM (												
SELECT CASE	WHEN											
		${assetCode}= ''null'' THEN										
			${assetType} ELSE 									
			            (									
							SELECT					
							CASE WHEN assetType IS NULL 					
							THEN ${assetType} ELSE assetType 					
							END as assetType					
							FROM					
							(					
								SELECT				
								CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6				
								     WHEN TYPE_8 =''F05'' THEN (				
								     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7				
								     ELSE TYPE_8||''_''||TYPE_6 END )				
									 END AS assetType 			
								FROM				
									FIN_PRODUCT_TYPE t 			
								WHERE				
								t.FINPROD_ID=${assetCode} and  t.BRANCH = ''0'' 				
							) t 					
						) end as VALUE						
				FROM dual								
				) m left join (								
				select DICT_CODE,''F01_''||ITEM_CODE AS ITEM_CODE,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''WINDTYPEONE''								
				union all								
				select DICT_CODE,''F02_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''FUND_ASSET_TYPE''								
				union all								
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_TYPE''								
				union all								
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_ASSET_TYPE''								
				union all								
				select DICT_CODE,''F06_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''ASSET_TYPE_PROJECT''								
				UNION ALL 								
				SELECT DICT_CODE,ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST WHERE DICT_CODE  IN (''PINAN_ASSET_TYPE'',''WINDTYPETWO'',''FUND_ASSET_SECOND_TYPE'',''ASSET_TYPE_PROJECT_TWO'')								
