INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('ZHKTZZCXZ', '04', 'SQL', 'with tmp as (select 											
case when assetType=''F01'' then ''PINAN_ASSET_TYPE,WINDTYPEONE,WINDTYPETWO''											
when  assetType=''F02'' then ''PINAN_ASSET_TYPE,FUND_ASSET_TYPE,FUND_ASSET_SECOND_TYPE''											
when  assetType=''F06'' then ''PINAN_ASSET_TYPE,ASSET_TYPE_PROJECT,ASSET_TYPE_PROJECT_TWO''											
when  assetType=''F05'' then ''PINAN_ASSET_TYPE,DEPO_ASSET_TYPE,DEPO_TYPE''											
else ''PINAN_ASSET_TYPE'' end ITEMCODE,assetMxType as VALUE											
from (											
	select DISTINCT assetType, case when assetMxType is null then assetType else assetMxType end as assetMxType from (										
		select 									
			 t4.TYPE_8 as assetType,								
			CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6								
			     WHEN TYPE_8 =''F05'' THEN (								
			     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7								
			     ELSE TYPE_8||''_''||TYPE_6 END )								
			END AS assetMxType 								
		from PTL_SEC_VALUTION t1									
		inner join FIN_PRODUCT_TYPE t4 on t1.FINPROD_ID = t4.FINPROD_ID									
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1									
		union all 									
		select 									
		 t4.TYPE_8 as assetType,t4.TYPE_8 as assetMxType									
		from PTL_SEC_VALUTION t1									
		inner join FIN_TRADE_PRODUCT t2	 on t1.FINPROD_ID = t2.FINPROD_ID								
		inner join FIN_PRODUCT_TYPE t4 on t1.FINPROD_ID = t4.FINPROD_ID									
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1									
		union all 									
		 SELECT									
		  t4.TYPE_8 as assetType,									
			CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6								
			     WHEN TYPE_8 =''F05'' THEN (								
			     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7								
			     ELSE TYPE_8||''_''||TYPE_6 END )								
			END AS assetMxType								
		  from TRD_PRODUCT_DEAL n									
		   inner join TRD_PRODUCT_DEAL_ADD t1  on n.TRADE_ID = t1.TRADE_ID									
		   inner join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID									
		  left join FIN_PRODUCT_TYPE t4 on t2.FINPROD_ID = t4.FINPROD_ID									
		  where t1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE=date''${valDate}''									
		  									
		 union all 									
		 SELECT									
		  t4.TYPE_8 as assetType,t4.TYPE_8 as assetMxType									
		  from TRD_PRODUCT_DEAL n									
		   inner join TRD_PRODUCT_DEAL_ADD t1  on n.TRADE_ID = t1.TRADE_ID									
		  inner join FIN_TRADE_PRODUCT t2 on n.FINPROD_ID = t2.FINPROD_ID AND t2.BRANCH=0									
		  inner join FIN_PRODUCT_TYPE t4 on n.FINPROD_ID = t4.FINPROD_ID									
		  where t1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE=date''${valDate}''									
		  									
		 ', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
----------过长截断	
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||'  union all 									
		 SELECT									
		  t4.TYPE_8 as assetType,									
			CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6								
			     WHEN TYPE_8 =''F05'' THEN (								
			     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7								
			     ELSE TYPE_8||''_''||TYPE_6 END )								
			END AS assetMxType								
		   from WFL_TRD_PRODUCT_DEAL_ADD m									
  			inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''								
		   inner join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID									
		  left join FIN_PRODUCT_TYPE t4 on t2.FINPROD_ID = t4.FINPROD_ID									
		  where m.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE=date''${valDate}''									
		  									
		 union all 									
		 SELECT									
		 t4.TYPE_8 as assetType,t4.TYPE_8 as assetMxType									
		   from WFL_TRD_PRODUCT_DEAL_ADD m									
  			inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''								
		  inner join FIN_TRADE_PRODUCT t2 on n.FINPROD_ID = t2.FINPROD_ID AND t2.BRANCH=0									
		   inner join FIN_PRODUCT_TYPE t4 on n.FINPROD_ID = t4.FINPROD_ID									
		  where m.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE=date''${valDate}''									
	 ) 										
    ) t											
) 											
