INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FKFSCPGLDXZC', '02', 'SQL', 'SELECT Y1.PORTFOLIO_ID AS RKEY,SUM(TRADE_AMT)  AS RVALUE 					
FROM(					
		 SELECT	 T1.PORTFOLIO_ID,SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) AS TRADE_AMT		
		 FROM PTL_SEC_VALUTION T1			
	     LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID=T2.FINPROD_ID 				
	     LEFT JOIN MST_BOND_CREDIT_RATING T3 ON T3.O_CODE=T2.Finprod_Market_Id				
	     WHERE  T1.CDATE = DATE''${valDate}''-1  AND T1.PORTFOLIO_ID!=T1.FINPROD_ID				
	     AND T2.FINPROD_TYPE2  =''F01'' AND T2.ISSUE_TYPE =''01''				
	     AND T3.GRADE_RESULT =''02''				
	     GROUP BY T1.PORTFOLIO_ID				
	 UNION ALL				
		 SELECT M.PORTFOLIO_ID,NVL(SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) AS TRADE_AMT			
		 FROM PTL_SEC_VALUTION M			
	     INNER JOIN FIN_PRODUCT N ON M.FINPROD_ID =N.FINPROD_ID AND N.FINPROD_TYPE2 =''F01''				
	     INNER JOIN FIN_PRODUCT_TYPE T3  ON N.FINPROD_ID =T3.FINPROD_ID  AND (T3.TYPE_4 IN (''B01'',''B02'',''B03'') OR (T3.TYPE_4 =''B05'' AND T3.TYPE_5=''01''))				
	     WHERE M.CDATE =DATE''${valDate}''-1				
	     AND M.PORTFOLIO_ID!=M.FINPROD_ID				
	     GROUP BY M.PORTFOLIO_ID				
) Y1 GROUP BY Y1.PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
