INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPZDHC', '01', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'whmcp', '2222222', sysdate, 'whmcp', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('GMZDDDZZQHJJ', '02', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	
	select
	sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY
	from PTL_SEC_VALUTION t1
	inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE2  IN (''F01'',''F06'',''F10'')
	where  t1.CDATE = date''${valDate}''-1
	group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME
	UNION ALL
	select sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY
	from (select t1.*
	from PTL_SEC_VALUTION t1
	inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE2  IN (''F01'',''F06'',''F10'')
	where  t1.CDATE = date''${valDate}''-1
	) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' )
	s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID
	) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('GMZDDDZZQHJJ', '01', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	
	select
	sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY
	from PTL_SEC_VALUTION t1
	inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE2  IN (''F01'',''F06'',''F10'')
	where  t1.CDATE = date''${valDate}''-1
	group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME
	UNION ALL
	select sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY
	from (select t1.*
	from PTL_SEC_VALUTION t1
	inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE2  IN (''F01'',''F06'',''F10'')
	where  t1.CDATE = date''${valDate}''-1
	) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' )
	s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID
	) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('GMZDDDZZQHJJ', '03', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	
	select
	sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY
	from PTL_SEC_VALUTION t1
	inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE2  IN (''F01'',''F06'',''F10'')
	where  t1.CDATE = date''${valDate}''-1
	group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME
	UNION ALL
	select sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY
	from (select t1.*
	from PTL_SEC_VALUTION t1
	inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE2  IN (''F01'',''F06'',''F10'')
	where  t1.CDATE = date''${valDate}''-1
	) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' )
	s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID
	) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('GMZDDDZZQHJJ', '04', 'SQL', 'select nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.FINPROD_ID as RKEY,s1.FINPROD_NAME RKEYCN from	
 (	
 select m.FINPROD_ID ,n.FINPROD_NAME,nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as RVALUE from PTL_SEC_VALUTION m	
	INNER  JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 IN (''F01'',''F06'',''F10'')
	where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' -1 group by m.FINPROD_ID,n.FINPROD_NAME
union ALL	
	  select n.FINPROD_ID ,m.FINPROD_NAME,
	 nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  +nvl(sum(decode(n.PS,''T04'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  +nvl(sum(decode(n.PS,''T52'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T03'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T06'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T09'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as  TRADE_AMT	
	  from  TRD_PRODUCT_DEAL n
	 INNER  JOIN FIN_PRODUCT m on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 IN (''F01'',''F06'',''F10'')
	    LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID
	  where  n1.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T04'',''T06'',''T07'',''T08'',''T09'',''T11'',''T52'')
	  group by n.FINPROD_ID,m.FINPROD_NAME
	
union ALL 	
   select 	n.FINPROD_ID ,s.FINPROD_NAME,
   nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  +nvl(sum(decode(n.PS,''T04'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  +nvl(sum(decode(n.PS,''T52'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T03'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T06'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T09'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as  TRADE_AMT	
  from WFL_TRD_PRODUCT_DEAL_ADD m	
  inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''	
  INNER  JOIN FIN_PRODUCT s on n.FINPROD_ID=s.FINPROD_ID and s.FINPROD_TYPE2 IN (''F01'',''F06'',''F10'')	
  where m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T04'',''T06'',''T07'',''T08'',''T09'',''T11'',''T52'') 	
  group by n.FINPROD_ID,s.FINPROD_NAME	
 ) s1  group by s1.FINPROD_ID,s1.FINPROD_NAME', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('GMZDDDZZQHJJ', '05', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.FINPROD_ID as RKEY,s1.FINPROD_NAME RKEYCN FROM (	
   select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as RVALUE,m.FINPROD_ID ,n.FINPROD_NAME  from PTL_SEC_VALUTION m	
 INNER  JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 IN (''F01'',''F06'',''F10'')	
 where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' group by m.FINPROD_ID,n.FINPROD_NAME	
 ) s1 group by s1.FINPROD_ID,s1.FINPROD_NAME', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('XJGZZYYHPJZCXJRZQGM', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from	
(	
  select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m	
  INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 =''F01'' and n.MDATE>=sysdate and n.MDATE<=add_months(sysdate, 12)	
  inner join FIN_PRODUCT_TYPE t3 on n.FINPROD_ID=t3.FINPROD_ID and (t3.TYPE_6 in (''B01'',''B03'') or (t3.TYPE_6=''B05'' AND t3.TYPE_7=''01''))  and t3.TYPE_8 =''F01''	
  where  m.PORTFOLIO_ID in ${portfolioCode}  and m.CDATE=date''${valDate}'' -1	
	
union ALL	
  select	
    nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  +nvl(sum(decode(n.PS,''T04'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  +nvl(sum(decode(n.PS,''T52'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T03'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T06'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T09'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as  TRADE_AMT  from TRD_PRODUCT_DEAL_ADD m	
  inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID	
  INNER JOIN FIN_PRODUCT t2 on t2.FINPROD_ID=n.FINPROD_ID and t2.FINPROD_TYPE2 =''F01'' and t2.MDATE>=sysdate and t2.MDATE<=add_months(sysdate, 12)	
  inner join FIN_PRODUCT_TYPE t3 on n.FINPROD_ID=t3.FINPROD_ID and (t3.TYPE_6 in (''B01'',''B03'') or (t3.TYPE_6=''B05'' AND t3.TYPE_7=''01'')) and t3.TYPE_8 =''F01''	
  where  m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T04'',''T06'',''T07'',''T08'',''T09'',''T11'',''T52'')	
	
union ALL	
  select	
   nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  +nvl(sum(decode(n.PS,''T04'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  +nvl(sum(decode(n.PS,''T52'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T03'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T06'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T09'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as  TRADE_AMT  from WFL_TRD_PRODUCT_DEAL_ADD m	
  inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''	
  INNER JOIN FIN_PRODUCT t2 on t2.FINPROD_ID=n.FINPROD_ID and t2.FINPROD_TYPE2 =''F01'' and t2.MDATE>=sysdate and t2.MDATE<=add_months(sysdate, 12)	
  inner join FIN_PRODUCT_TYPE t3 on n.FINPROD_ID=t3.FINPROD_ID and (t3.TYPE_6 in (''B01'',''B03'') or (t3.TYPE_6=''B05'' AND t3.TYPE_7=''01'')) and t3.TYPE_8 =''F01''	
  where m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T04'',''T06'',''T07'',''T08'',''T09'',''T11'',''T52'')	
	
)', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('XJGZZYYHPJZCXJRZQGM', '02', 'SQL', 'select y1.PORTFOLIO_ID as RKEY,sum(TRADE_AMT)  as RVALUE from	
(	
  select m.PORTFOLIO_ID,nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m	
  INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 =''F01'' and n.MDATE>=date''${valDate}'' and n.MDATE<=add_months(date''${valDate}'', 12)	
  inner join FIN_PRODUCT_TYPE t3 on n.FINPROD_ID=t3.FINPROD_ID and (t3.TYPE_6 in (''B01'',''B03'') or (t3.TYPE_6=''B05'' AND t3.TYPE_7=''01''))  and t3.TYPE_8 =''F01''	
  where  m.CDATE=date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID group by m.PORTFOLIO_ID	
	
	union all
   select t.PTL_BAG_ID as RKEY,	
   ( select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m	
  INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 =''F01'' and n.MDATE>=date''${valDate}'' and n.MDATE<=add_months(date''${valDate}'', 12)	
  inner join FIN_PRODUCT_TYPE t3 on n.FINPROD_ID=t3.FINPROD_ID and (t3.TYPE_6 in (''B01'',''B03'') or (t3.TYPE_6=''B05'' AND t3.TYPE_7=''01''))  and t3.TYPE_8 =''F01''	
  where  m.CDATE=date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID	AND 
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)
   )	
   from RSK_PORTFOLIO_PACKAGE t	
   	
) y1 group by y1.PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPZZC', '05', 'SQL', 'SELECT NVL(SUM(TDY_ASSET_VALUE),0) AS amount		
FROM PTL_PORTFOLIO_VALUATION		
WHERE PORTFOLIO_ID IN ${portfolioCode} AND CDATE = date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('GZQSZHZZQTZJJSZ', '03', 'SQL', 'SELECT S1.RVALUE,S1.RKEY FROM (		
		SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,
		T2.FINPROD_ID RKEY FROM  FIN_PRODUCT t2
		LEFT JOIN (
	    SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno	
		FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
		) BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID
		WHERE T2.FINPROD_TYPE2 =''F01'' 
UNION ALL		
	SELECT RVALUE,RKEY FROM (	
		SELECT nvl(sum(JIJING.tradeAmount),0) RVALUE,
		T2.FINPROD_ID RKEY FROM FIN_PRODUCT t2
		LEFT JOIN (
		SELECT FINPROD_ID,nvl(VALUATION,1)*nvl(C_SHARES,0) AS tradeAmount FROM 	
		 	(	
		 	    SELECT s1.FINPROD_ID,CASE s2.TYPE_6 WHEN ''F01'' THEN 1 else VALUATION END VALUATION,C_SHARES, RANK() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.VAL_DATE DESC ) AS rowno	
				FROM FIN_PRODUCT_VALUATION s1
				LEFT JOIN (SELECT m1.FINPROD_MARKET_ID,m2.TYPE_6 FROM FIN_PRODUCT m1 INNER JOIN FIN_PRODUCT_TYPE m2 ON m1.FINPROD_ID=m2.FINPROD_ID AND m2.BRANCH=0 AND m2.TYPE_8=''F02'') s2
				ON s1.FINPROD_ID=s2.FINPROD_MARKET_ID
				WHERE s1.VAL_DATE<=date''${valDate}''
			) WHERE rowno=1	
		) JIJING ON t2.FINPROD_MARKET_ID=JIJING.FINPROD_ID
		WHERE  T2.FINPROD_TYPE2 =''F06'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID
	) group by RVALUE,RKEY	
UNION ALL		
	SELECT RVALUE,RKEY FROM (	
		SELECT (SELECT nvl(s.C_SHARES,0)*nvl(s.CLOSE_PRICE,0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
		T2.FINPROD_ID RKEY FROM FIN_PRODUCT t2
		WHERE  T2.FINPROD_TYPE2 =''F10'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID
	) group by RVALUE,RKEY	
) S1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
