	SELECT (SELECT nvl(s.C_SHARES,0)*nvl(s.CLOSE_PRICE,0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F10''	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''	
	)	
) S1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FBSLCCPDQRHKFSLCCP', '02', 'SQL', 'select n.PORTFOLIO_ID RKEY,MDATE as RVALUE from PTL_PORTFOLIO m INNER JOIN PA_PTL_PORTFOLIO n 
  ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''01'' 
  UNION ALL 
  SELECT PORTFOLIO_ID ,OPEN_VDATE FROM (SELECT m.PORTFOLIO_ID,y.OPEN_VDATE ,rank() over(PARTITION BY m.PORTFOLIO_ID ORDER BY y.OPEN_VDATE asc) AS rowno  from PTL_PORTFOLIO m 
  INNER JOIN  FIN_CASH_INFO n ON n.FINPROD_ID=''F16_''||m.PORTFOLIO_ID  AND n.CASH_TYPE_1=''01'' AND n.CASH_TYPE_2=''C01''
  INNER JOIN  FIN_OPEN_PLAN y ON y.CASH_ID=n.CASH_ID AND y.OPEN_TYPE IN (''02'',''03'')
  INNER JOIN  PA_PTL_PORTFOLIO s   on m.PORTFOLIO_ID=s.PORTFOLIO_ID AND s.OPEN_TYPE=''02''
  WHERE    y.OPEN_VDATE>date''${valDate}''  ORDER BY y.OPEN_VDATE ASC) WHERE  rowno=1', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
