INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FBSLCCPDQRHKFSLCCP', '04', 'SQL', 'select ceil(MDATE-sysdate) as mdate from PTL_PORTFOLIO m INNER JOIN PA_PTL_PORTFOLIO n 
  ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''01'' where n.PORTFOLIO_ID in ${portfolioCode}
  UNION ALL 
  SELECT mdate FROM (SELECT ceil(y.OPEN_VDATE-sysdate) as mdate  from PTL_PORTFOLIO m 
  INNER JOIN  FIN_CASH_INFO n ON n.FINPROD_ID=''F16_''||m.PORTFOLIO_ID  AND n.CASH_TYPE_1=''01'' AND n.CASH_TYPE_2=''C01''
  INNER JOIN  FIN_OPEN_PLAN y ON y.CASH_ID=n.CASH_ID AND y.OPEN_TYPE IN (''02'',''03'')
  INNER JOIN  PA_PTL_PORTFOLIO s   on m.PORTFOLIO_ID=s.PORTFOLIO_ID AND s.OPEN_TYPE=''02''
  WHERE  m.PORTFOLIO_ID in ${portfolioCode} AND  y.OPEN_VDATE>date''${valDate}'' ORDER BY y.OPEN_VDATE ASC) WHERE  rownum=1', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
