INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('SSGSKLTGB', '04', 'SQL', 'SELECT DISTINCT RVALUE,RKEY,RKEYCN FROM (		
	SELECT RVALUE,RKEY,RKEYCN FROM (	
	SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID 	
	inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''-1	
	)	
UNION ALL		
	SELECT RVALUE,RKEY,RKEYCN FROM (	
	SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM TRD_PRODUCT_DEAL t1	
	INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON t1.TRADE_ID =n1.TRADE_ID	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID 	
	inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
	WHERE n1.PORTFOLIO_ID IN ${portfolioCode} AND t1.TRADE_DATE=date''${valDate}''	
	)	
UNION ALL		
	SELECT RVALUE,RKEY,RKEYCN FROM (	
	SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM WFL_TRD_PRODUCT_DEAL_ADD t1	
	inner join WFL_TRD_PRODUCT_DEAL n on t1.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''	
	INNER JOIN FIN_PRODUCT t2 ON n.FINPROD_ID=t2.FINPROD_ID 	
	inner join FIN_PRODUCT_TYPE fpt on n.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE=date''${valDate}''	
	)	
) S1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('SSGSKLTGB', '05', 'SQL', 'SELECT RVALUE,RKEY,RKEYCN FROM (		
