INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('NHGZJYE', '01', 'SQL', 'select m.PORTFOLIO_ID AS RKEY,nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as  RVALUE from PTL_SEC_VALUTION m	
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'')	 AND n.BRANCH=0
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID	
	
union all	
   select t.PTL_BAG_ID as RKEY,	
   ( select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as  RVALUE from PTL_SEC_VALUTION m	
	INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'') AND n.BRANCH=0
	where    m.CDATE =date''${valDate}''-1  AND 
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)
   )	
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('SONDZGMZCGLZTZQ', '04', 'SQL', 'WITH BOND AS (		
  SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno		
		FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
)		
SELECT DISTINCT RVALUE,RKEY,RKEYCN FROM (		
	SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,	
	T2.FINPROD_ID RKEY,t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''-1	
UNION ALL		
	SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM TRD_PRODUCT_DEAL t1	
	INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON t1.TRADE_ID =n1.TRADE_ID	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
	WHERE n1.PORTFOLIO_ID IN ${portfolioCode} AND t1.TRADE_DATE=date''${valDate}''	
UNION ALL		
	SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM WFL_TRD_PRODUCT_DEAL_ADD t1	
	inner join WFL_TRD_PRODUCT_DEAL n on t1.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''	
	INNER JOIN FIN_PRODUCT t2 ON n.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE=date''${valDate}''	
) S1', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('SONDZGMZCGLZTZQ', '05', 'SQL', 'SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,	
T2.FINPROD_ID RKEY,t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	
INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	
LEFT JOIN (	
    SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno	
	FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
) BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
