INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FGKFXZQZC', '05', 'SQL', 'select 	
nvl(sum(nvl(targetData.VALUE, 0)), 0) as RVALUE	
from	
(	
select 	
  sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0))  as  VALUE from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2  on t1.FINPROD_ID=t2.FINPROD_ID and t2.FINPROD_TYPE2 =''F01'' and t2.ISSUE_TYPE = ''02''	
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID = fpt.FINPROD_ID and fpt.TYPE_6 != ''B17''	
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE =date''${valDate}'' 	
group by t1.PORTFOLIO_ID 	
) targetData', 'portfolioCode', 'Y', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('SSGSKLTGB', '03', 'SQL', 'SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(		
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY		
	from FIN_PRODUCT t2 	
	inner join FIN_PRODUCT_TYPE fpt on t2.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
	GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('TZDYSSGSFXGP', '01', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	
select	
 sum(nvl(SHARE_AMT,0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	
from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID 	
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
where  t1.CDATE = date''${valDate}''-1	
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	
UNION ALL	
  select sum(nvl(SHARE_AMT,0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	
 from (select t1.*	
from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID 	
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
where  t1.CDATE = date''${valDate}''-1	
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}''-1 )	
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID	
 ) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('SSGSKLTGB', '01', 'SQL', 'SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(		
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY		
	from FIN_PRODUCT t2 	
	inner join FIN_PRODUCT_TYPE fpt on t2.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
	GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('TZDYSSGSFXGP', '04', 'SQL', 'select nvl(sum(nvl(TRADE_AMT, 0)),0) as RVALUE ,s1.FINPROD_ID as RKEY,s1.FINPROD_NAME RKEYCN from	
(	
  select t1.FINPROD_ID ,n.FINPROD_NAME,nvl(sum(nvl(SHARE_AMT,0)),0) as  TRADE_AMT from PTL_SEC_VALUTION t1	
  INNER  JOIN FIN_PRODUCT n on t1.FINPROD_ID=n.FINPROD_ID 	
  inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
  where t1.PORTFOLIO_ID in ${portfolioCode}  and  t1.CDATE=date''${valDate}''-1	
  group by t1.FINPROD_ID,n.FINPROD_NAME	
union all	
   select t2.FINPROD_ID ,m.FINPROD_NAME,	
  nvl(sum(decode(t2.PS,''T01'',decode(TRADE_STATUS,''03'',t2.TRADE_AMT*-1,t2.TRADE_AMT))),0)	
  - nvl(sum(decode(t2.PS,''T02'',decode(TRADE_STATUS,''03'',t2.TRADE_AMT*-1,t2.TRADE_AMT))), 0) 	
  from TRD_PRODUCT_DEAL_ADD t1	
  inner join TRD_PRODUCT_DEAL t2 on t1.TRADE_ID=t2.TRADE_ID 	
   INNER  JOIN FIN_PRODUCT m on m.FINPROD_ID=t2.FINPROD_ID 	
   inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
  where t1.PORTFOLIO_ID in ${portfolioCode} and  t2.TRADE_DATE=date''${valDate}'' and t2.PS in (''T01'',''T02'')	
   group by t2.FINPROD_ID,m.FINPROD_NAME	
union all	
   select 	t2.FINPROD_ID ,s.FINPROD_NAME,
  nvl(sum(decode(t2.PS,''T01'',decode(TRADE_STATUS,''03'',t2.TRADE_AMT*-1,t2.TRADE_AMT))),0)	
   - nvl(sum(decode(t2.PS,''T02'',decode(TRADE_STATUS,''03'',t2.TRADE_AMT*-1,t2.TRADE_AMT))), 0) 	
  from WFL_TRD_PRODUCT_DEAL_ADD t1	
  inner join WFL_TRD_PRODUCT_DEAL t2 on t1.TRADE_ID=t2.TRADE_ID   and t2.TRADE_STATUS != ''03''	
  INNER  JOIN FIN_PRODUCT s on t2.FINPROD_ID=s.FINPROD_ID 	
  inner join FIN_PRODUCT_TYPE fpt on t2.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
  where t1.PORTFOLIO_ID in ${portfolioCode}  and t2.TRADE_DATE=date''${valDate}'' and t2.PS in (''T01'',''T02'')	
   group by t2.FINPROD_ID,s.FINPROD_NAME	
) s1  group by s1.FINPROD_ID,s1.FINPROD_NAME', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('TZDYSSGSFXGP', '05', 'SQL', 'select nvl(sum(nvl(SHARE_AMT,0)),0) as RVALUE, t1.FINPROD_ID as RKEY,t2.FINPROD_NAME AS RKEYCN from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
