INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('JZCCB', '02', 'SQL', 'SELECT PTL_PORTFOLIO_VALUATION1.PORTFOLIO_ID portfolioId,nvl(sum(PTL_PORTFOLIO_VALUATION1.TDY_ASSET_NETVALUE),0) AS  CST, PTL_PORTFOLIO_VALUATION1.CDATE cdate
FROM PTL_PORTFOLIO_VALUATION PTL_PORTFOLIO_VALUATION1
GROUP BY
PTL_PORTFOLIO_VALUATION1.PORTFOLIO_ID,
PTL_PORTFOLIO_VALUATION1.CDATE
UNION ALL
SELECT DTL.PTL_BAG_ID portfolioId, nvl(sum(PTL_PORTFOLIO_VALUATION2.TDY_ASSET_NETVALUE),0) AS CST,PTL_PORTFOLIO_VALUATION2.CDATE cdate
FROM PTL_PORTFOLIO_VALUATION PTL_PORTFOLIO_VALUATION2
LEFT JOIN RSK_PORTFOLIO_PACKAGE_DTL DTL ON DTL.PORTFOLIO_ID = PTL_PORTFOLIO_VALUATION2.PORTFOLIO_ID
where PTL_PORTFOLIO_VALUATION2.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')
GROUP BY
DTL.PTL_BAG_ID,
PTL_PORTFOLIO_VALUATION2.CDATE', 'portfolioCode', 'N', 'paopi1', 'jsadjflsajfsdkl', sysdate, 'paopi1', sysdate);
