INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('JZCSZ', '03', 'SQL', 'SELECT PTL_PORTFOLIO_VALUATION1.PORTFOLIO_ID portfolioId,nvl(sum(PTL_PORTFOLIO_VALUATION1.TDY_ASSET_NETVALUE),0) AS  MKT, PTL_PORTFOLIO_VALUATION1.CDATE cdate
FROM PTL_PORTFOLIO_VALUATION PTL_PORTFOLIO_VALUATION1
GROUP BY
PTL_PORTFOLIO_VALUATION1.PORTFOLIO_ID,
PTL_PORTFOLIO_VALUATION1.CDATE
UNION ALL
SELECT DTL.PTL_BAG_ID portfolioId, nvl(sum(PTL_PORTFOLIO_VALUATION2.TDY_ASSET_NETVALUE),0) AS MKT,PTL_PORTFOLIO_VALUATION2.CDATE cdate
FROM PTL_PORTFOLIO_VALUATION PTL_PORTFOLIO_VALUATION2
LEFT JOIN RSK_PORTFOLIO_PACKAGE_DTL DTL ON DTL.PORTFOLIO_ID = PTL_PORTFOLIO_VALUATION2.PORTFOLIO_ID
where PTL_PORTFOLIO_VALUATION2.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')
GROUP BY
DTL.PTL_BAG_ID,
PTL_PORTFOLIO_VALUATION2.CDATE', 'portfolioCode', 'N', 'paopi1', 'jsadjflsajfsdkl', sysdate, 'paopi1', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('JZCSZ', '05', 'SQL', 'SELECT  PTL_PORTFOLIO_VALUATION.CDATE AS cdate,NVL(SUM(TDY_ASSET_NETVALUE),0) AS MKT
FROM PTL_PORTFOLIO_VALUATION
WHERE PTL_PORTFOLIO_VALUATION.PORTFOLIO_ID in ${portfolioCode}
GROUP BY
PTL_PORTFOLIO_VALUATION.PORTFOLIO_ID,
PTL_PORTFOLIO_VALUATION.CDATE', 'portfolioCode', 'N', 'paopi1', 'jsadjflsajfsdkl', sysdate, 'paopi1', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('DBJYSZJJ', '03', 'SQL', 'SELECT secid AS RKEY,netprice AS RVALUE
FROM
(SELECT t2.FINPROD_ID as secid,t1.NETPRICE as netprice,rank() over (partition by t2.FINPROD_ID order by t1.VALUE_DATE desc) rk
 FROM MST_BOND_VALUATION_INFO t1
 inner JOIN FIN_PRODUCT t2 ON t2.FINPROD_MARKET_ID=t1.SEC_ID
 WHERE t1.VALUE_DATE<=DATE''${valDate}''
 AND T1.VALUE_SOURCE =(CASE WHEN t2.TRADE_MARKET IN(''03'',''04'') THEN ''CSD'' ELSE ''CBC'' END)
 GROUP BY t2.FINPROD_ID,t1.NETPRICE, t1.VALUE_DATE
)where rk=1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FBZHZQLZCDYE', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from			
(			
	select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m		
  inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))			
  where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1			
union ALL			
  select			
  nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as  TRADE_AMT  from TRD_PRODUCT_DEAL_ADD m			
  inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID			
 inner join FIN_PRODUCT_TYPE fpt on n.FINPROD_ID=fpt.FINPROD_ID  and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))			
  where m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T07'',''T08'')			
union ALL			
  select			
  nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as  TRADE_AMT  from WFL_TRD_PRODUCT_DEAL_ADD m			
  inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''			
  inner join FIN_PRODUCT_TYPE fpt on n.FINPROD_ID=fpt.FINPROD_ID  and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))			
  where m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T07'',''T08'') 			
)', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FBZHZQLZCDYE', '05', 'SQL', 'select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m			
INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 IN (''F18'',''F01'')			
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID 	AND ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))		
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
