INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('XYZDBJYJJ', '04', 'SQL', 'select n.UNIT_CPRICE as RVALUE,n.FINPROD_ID RKEY
  from TRD_PRODUCT_DEAL_ADD m
  inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 =''F01''
  INNER JOIN FIN_PRODUCT_TYPE s ON s.FINPROD_ID=n.FINPROD_ID AND s.BRANCH=0 AND s.TYPE_6 IN (''B10'',''B11'',''B13'',''B14'',''B15'',''B04'',''B16'',''B05'',''B06'',''B07'',''B08'',''B09'')
  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}''
', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FBZHZQLZCDYE', '01', 'SQL', 'SELECT RKEY,SUM(RVALUE) RVALUE FROM (			
select m.PORTFOLIO_ID AS RKEY,nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as  RVALUE from PTL_SEC_VALUTION m			
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))			
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID			
 union all			
   select t.PTL_BAG_ID as RKEY,			
   ( select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as  RVALUE from PTL_SEC_VALUTION m			
   inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))			
	where    m.CDATE =date''${valDate}''-1  AND 		
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)		
   )			
from RSK_PORTFOLIO_PACKAGE t			
) GROUP BY RKEY', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('DBJYSZJJ', '05', 'SQL', 'SELECT secid AS RKEY,netprice AS RVALUE
FROM
(SELECT t2.FINPROD_ID as secid,t1.NETPRICE as netprice,rank() over (partition by t2.FINPROD_ID order by t1.VALUE_DATE desc) rk
 FROM MST_BOND_VALUATION_INFO t1
 inner JOIN FIN_PRODUCT t2 ON t2.FINPROD_MARKET_ID=t1.SEC_ID
 WHERE t1.VALUE_DATE<=DATE''${valDate}''
 AND T1.VALUE_SOURCE =(CASE WHEN t2.TRADE_MARKET IN(''03'',''04'') THEN ''CSD'' ELSE ''CBC'' END)
 GROUP BY t2.FINPROD_ID,t1.NETPRICE, t1.VALUE_DATE
)where rk=1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
