INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPZZC', '02', 'SQL', 'WITH  temp  as(			
  SELECT 			
       DISTINCT t2.PORTFOLIO_ID ,			
       mujiData.mujiAmt  as AMOUNT			
       from  PTL_PORTFOLIO t2			
       left join 			
       (			
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1			
       WHERE			
           t1.PS in (''C1'', ''C2'')			
           and t1.SETTLE_DATE <= date''${valDate}''	and t1.TRADE_STATUS=''01''		
       group by t1.PORTFOLIO_ID			
       ) mujiData			
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID			
       where  t2.VDATE=date''${valDate}''			
 UNION ALL			
      SELECT 			
       DISTINCT t1.PORTFOLIO_ID RKEY,			
        nvl(TDY_ASSET_VALUE,0) as RVALUE			
       from PTL_PORTFOLIO_VALUATION t1			
       where  t1.CDATE=date''${valDate}''-1 			
 )			
   SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp			
union all			
    select m.PTL_BAG_ID as RKEY,		 	
   (		 	
        SELECT sum(AMOUNT) FROM ( 			
         SELECT PORTFOLIO_ID,AMOUNT FROM temp			
	   	 ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1	 
	     inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)		
   ) AS RVALUE		 	
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('DCPZQJQPJJQ', '02', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'admin', '001', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('DCPZQJQPJJQ', '05', 'SQL', 'select SUM(dataOne.chiCangMianE/dataTwo.zongHe) AS RVALE 
from( 
	select ( 
       case   
		   when B.FINPROD_TYPE2=''F01'' AND D.ENCASH_YEARS IS NOT NULL then D.ENCASH_YEARS 
		   when B.FINPROD_TYPE2=''F01'' AND C.TYPE_6 IN (''B03'', ''B04'') then (B.MDATE - DATE ''${valDate}'') / 365 
		   when B.FINPROD_TYPE2=''F01'' AND B.IS_RIGHT = ''Y'' then ((SELECT MIN(FEP.EXERCISE_DATE) 
														FROM FIN_EXERCISE_PLAN FEP 
														WHERE FEP.FINPROD_ID   = t1.FINPROD_ID 
														AND FEP.FINPROD_TYPE2  = ''F01'' 
														AND FEP.EXERCISE_DATE >= DATE ''${valDate}'' 
														) - DATE ''${valDate}'' 
													   ) / 365 
		   when B.FINPROD_TYPE2=''F01'' then (B.MDATE - DATE ''${valDate}'') / 365 
		   else 0 
		   end)*(NVL(t1.SHARE_AMT, 0)* 100) AS chiCangMianE 
		   FROM PTL_SEC_VALUTION t1 
		   INNER JOIN FIN_PRODUCT B 
		   ON t1.FINPROD_ID    = B.FINPROD_ID 
		   AND B.FINPROD_TYPE2 = ''F01'' 
		   INNER JOIN FIN_PRODUCT_TYPE C 
		   ON t1.FINPROD_ID = C.FINPROD_ID 
		   INNER JOIN PTL_PORTFOLIO pp 
		   ON t1.PORTFOLIO_ID = pp.PORTFOLIO_ID 
		   LEFT JOIN INTERF_PAYHSRCCBVLT D 
		   ON DECODE(B.TRADE_MARKET, ''01'', ''IB'', ''03'', ''SH'', ''04'', ''SZ'') 
		    	|| B.FINPROD_MARKET_ID = D.SECID 
		    	|| DECODE(B.TRADE_MARKET, ''01'', ''.IB'', ''03'', ''.SH'', ''04'', ''.SZ'') 
		   AND D.CDATE            = TO_CHAR(DATE ''${valDate}'', ''yyyy-MM-dd'') 
		   WHERE t1.PORTFOLIO_ID IN ${portfolioCode} 
		   AND t1.CDATE           = DATE ''${valDate}'' 
	) dataOne, 
  ( 
	SELECT
       SUM(t1.SHARE_AMT*100) as zongHe 
		   FROM PTL_SEC_VALUTION t1 
		   INNER JOIN FIN_PRODUCT B 
		   ON t1.FINPROD_ID    = B.FINPROD_ID 
		   AND B.FINPROD_TYPE2 = ''F01'' 
		   INNER JOIN FIN_PRODUCT_TYPE C 
		   ON t1.FINPROD_ID = C.FINPROD_ID 
		   INNER JOIN PTL_PORTFOLIO pp 
		   ON t1.PORTFOLIO_ID = pp.PORTFOLIO_ID 
		   LEFT JOIN INTERF_PAYHSRCCBVLT D 
		   ON DECODE(B.TRADE_MARKET, ''01'', ''IB'', ''03'', ''SH'', ''04'', ''SZ'') 
		    	|| B.FINPROD_MARKET_ID = D.SECID 
		    	|| DECODE(B.TRADE_MARKET, ''01'', ''.IB'', ''03'', ''.SH'', ''04'', ''.SZ'') 
		   AND D.CDATE            = TO_CHAR(DATE ''${valDate}'', ''yyyy-MM-dd'') 
		   WHERE t1.PORTFOLIO_ID IN ${portfolioCode} 
		   AND t1.CDATE           = DATE ''${valDate}'' 
	) dataTwo', 'portfolioCode', 'N', 'admin', '001', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('DCPZQJQPJJQ', '04', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'admin', '001', sysdate, 'admin', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPZCLZCGM', '02', 'SQL', 'select PORTFOLIO_ID RKEY,sum(TRADE_AMT) as RVALUE from	 
 (	 
select m.PORTFOLIO_ID,nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as TRADE_AMT from PTL_SEC_VALUTION m	 
  INNER JOIN FIN_PRODUCT_ADD PFP on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''	  
where   m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID  group by m.PORTFOLIO_ID	 
union all	 
select  m.PORTFOLIO_ID,	 
  sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m	 
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'') and n.BRANCH=0		 
where  m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID	 
) group by PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
