INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPZCLZCGM', '03', 'SQL', 'select PORTFOLIO_ID RKEY,sum(TRADE_AMT) as RVALUE from	 
 (	 
select m.PORTFOLIO_ID,nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as TRADE_AMT from PTL_SEC_VALUTION m	 
  INNER JOIN FIN_PRODUCT_ADD PFP on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''	  
where   m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID  group by m.PORTFOLIO_ID	 
union all	 
select  m.PORTFOLIO_ID,	 
  sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m	 
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'') and n.BRANCH=0		 
where  m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID	 
) group by PORTFOLIO_ID', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
