INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FSMCPBDTZWSSQYGQ', '03', 'SQL', 'SELECT
	m.PORTFOLIO_ID RKEY,n.RAISE_TYPE || n.OPEN_TYPE || ''||'' ||y1.ITEM_VALUE||y2.ITEM_VALUE AS RVALUE
FROM
	PTL_PORTFOLIO m
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FSMCPBDTZWSSQYGQ', '02', 'SQL', 'SELECT
	m.PORTFOLIO_ID RKEY,n.RAISE_TYPE || n.OPEN_TYPE || ''||'' ||y1.ITEM_VALUE||y2.ITEM_VALUE AS RVALUE
FROM
	PTL_PORTFOLIO m
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FSMCPBDTZWSSQYGQ', '05', 'SQL', 'SELECT
	n.RAISE_TYPE || n.OPEN_TYPE AS VALUE,y1.ITEM_VALUE||y2.ITEM_VALUE as ASSETCODE
FROM
	PTL_PORTFOLIO m
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''
WHERE
	m.PORTFOLIO_ID IN ${portfolioCode}', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
