INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FSMCPBDTZWSSQYGQ', '01', 'SQL', 'SELECT
	m.PORTFOLIO_ID RKEY,n.RAISE_TYPE || n.OPEN_TYPE || ''||'' ||y1.ITEM_VALUE||y2.ITEM_VALUE AS RVALUE
FROM
	PTL_PORTFOLIO m
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPJZCJZ', '03', 'SQL', 'WITH  temp  as(			
  SELECT 			
       DISTINCT t2.PORTFOLIO_ID ,			
       mujiData.mujiAmt  as AMOUNT			
       from  PTL_PORTFOLIO t2			
       left join 			
       (			
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1			
       WHERE  t1.PS in (''C1'', ''C2'')	 and t1.SETTLE_DATE <= date''${valDate}'' and t1.TRADE_STATUS=''01''		
       group by t1.PORTFOLIO_ID			
       ) mujiData			
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID			
       where  t2.VDATE=date''${valDate}''			
 UNION ALL			
      SELECT 			
       DISTINCT t1.PORTFOLIO_ID RKEY,			
        nvl(TDY_ASSET_NETVALUE,0) as RVALUE			
       from PTL_PORTFOLIO_VALUATION t1			
       where  t1.CDATE=date''${valDate}''-1 			
 )			
 SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp			
union all			
   select m.PTL_BAG_ID as RKEY,		 	
   (		 	
        SELECT sum(AMOUNT) FROM ( 			
          SELECT PORTFOLIO_ID,AMOUNT FROM temp			
	   	 ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1	 
	     inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)		
   ) AS RVALUE		 	
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('DBJYSZJJ', '02', 'SQL', 'SELECT secid AS RKEY,netprice AS RVALUE
FROM
(SELECT t2.FINPROD_ID as secid,t1.NETPRICE as netprice,rank() over (partition by t2.FINPROD_ID order by t1.VALUE_DATE desc) rk
 FROM MST_BOND_VALUATION_INFO t1
 inner JOIN FIN_PRODUCT t2 ON t2.FINPROD_MARKET_ID=t1.SEC_ID
 WHERE t1.VALUE_DATE<=DATE''${valDate}''
 AND T1.VALUE_SOURCE =(CASE WHEN t2.TRADE_MARKET IN(''03'',''04'') THEN ''CSD'' ELSE ''CBC'' END)
 GROUP BY t2.FINPROD_ID,t1.NETPRICE, t1.VALUE_DATE
)where rk=1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('XYZDBJYJJ', '05', 'SQL', 'select n.UNIT_CPRICE as RVALUE,n.FINPROD_ID RKEY
  from TRD_PRODUCT_DEAL_ADD m
  inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 =''F01''
  INNER JOIN FIN_PRODUCT_TYPE s ON s.FINPROD_ID=n.FINPROD_ID AND s.BRANCH=0 AND s.TYPE_6 IN (''B10'',''B11'',''B13'',''B14'',''B15'',''B04'',''B16'',''B05'',''B06'',''B07'',''B08'',''B09'')
  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPZZC', '04', 'SQL', 'select sum(amount) AS amount from			
(			
   select sum(amount) as amount			
   from			
   (			
     SELECT 			
       DISTINCT t2.PORTFOLIO_ID ,			
       mujiData.mujiAmt  as AMOUNT			
       from  PTL_PORTFOLIO t2			
       left join 			
       (			
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1			
       WHERE  t1.PS in (''C1'', ''C2'')	  and t1.SETTLE_DATE <= date''${valDate}'' and t1.TRADE_STATUS=''01''		
       group by t1.PORTFOLIO_ID			
       ) mujiData			
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID			
       where  t2.VDATE=date''${valDate}'' and t2.PORTFOLIO_ID in ${portfolioCode}			
   UNION ALL			
      SELECT 			
       DISTINCT t1.PORTFOLIO_ID RKEY,			
        nvl(TDY_ASSET_VALUE,0) as RVALUE			
       from PTL_PORTFOLIO_VALUATION t1			
       where  t1.CDATE=date''${valDate}''-1 and t1.PORTFOLIO_ID in ${portfolioCode}			
   )			
  union all			
    select			
     nvl(sum(decode(n.PS,''C1'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  +nvl(sum(decode(n.PS,''C2'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  +nvl(sum(decode(n.PS,''C3'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  -nvl(sum(decode(n.PS,''C4'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  -nvl(sum(decode(n.PS,''C5'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
  -nvl(sum(decode(n.PS,''C6'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)			
	-nvl(sum(decode(n.PS,''C7'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C9'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C12'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C13'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C14'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C15'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C16'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C17'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C18'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C19'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as amount		
    from TRD_PRODUCT_DEAL_ADD m			
    inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID			
    where m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}'' group by m.PORTFOLIO_ID		
    ', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' union ALL		
    select nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))), 0)		
    - nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))), 0) as TRADE_AMT		
    from TRD_PRODUCT_DEAL_ADD m		
    inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 in (''F02'',''F08'',''F25'',''F04'')		
    where  m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T07'')		
 		
  union all		
    select		
     nvl(sum(decode(n.PS,''C1'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
  +nvl(sum(decode(n.PS,''C2'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
  +nvl(sum(decode(n.PS,''C3'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
  -nvl(sum(decode(n.PS,''C4'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
  -nvl(sum(decode(n.PS,''C5'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
  -nvl(sum(decode(n.PS,''C6'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		
	-nvl(sum(decode(n.PS,''C7'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C9'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C12'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C13'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C14'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C15'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C16'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C17'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C18'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
	-nvl(sum(decode(n.PS,''C19'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as amount	
    from WFL_TRD_PRODUCT_DEAL_ADD m		
    inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''		
    where m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}'' group by m.PORTFOLIO_ID		
   union ALL		
    select nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))), 0)		
    - nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))), 0) as TRADE_AMT		
    from WFL_TRD_PRODUCT_DEAL_ADD m		
    inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 in (''F02'',''F08'',''F25'',''F04'') and n.TRADE_STATUS != ''03''		
    where  m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T07'') 		
)'  where PARA_CODE = 'CPZZC' and PARA_GRANULARITY='04';
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPZZC', '03', 'SQL', 'WITH  temp  as(			
  SELECT 			
       DISTINCT t2.PORTFOLIO_ID ,			
       mujiData.mujiAmt  as AMOUNT			
       from  PTL_PORTFOLIO t2			
       left join 			
       (			
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1			
       WHERE			
           t1.PS in (''C1'', ''C2'')			
           and t1.SETTLE_DATE <= date''${valDate}''	and t1.TRADE_STATUS=''01''		
       group by t1.PORTFOLIO_ID			
       ) mujiData			
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID			
       where  t2.VDATE=date''${valDate}''			
 UNION ALL			
      SELECT 			
       DISTINCT t1.PORTFOLIO_ID RKEY,			
        nvl(TDY_ASSET_VALUE,0) as RVALUE			
       from PTL_PORTFOLIO_VALUATION t1			
       where  t1.CDATE=date''${valDate}''-1 			
 )			
   SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp			
union all			
    select m.PTL_BAG_ID as RKEY,		 	
   (		 	
        SELECT sum(AMOUNT) FROM ( 			
         SELECT PORTFOLIO_ID,AMOUNT FROM temp			
	   	 ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1	 
	     inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)		
   ) AS RVALUE		 	
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('CPZCLZCGM', '05', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from		
 (		
select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)),0) as TRADE_AMT from PTL_SEC_VALUTION m		
  INNER JOIN FIN_PRODUCT_ADD PFP		
  on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''		
   LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=0		
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' AND m.PORTFOLIO_ID!=m.FINPROD_ID		
union all		
select		
  sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0)) as  TRADE_AMT from PTL_SEC_VALUTION m		
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'') AND n.BRANCH=0		
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''		
)', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);

INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('DYGNFDBJYJE', '01', 'SQL', 'with temp as (select  m.FINPROD_ID, 
case when m.FINPROD_TYPE2 = ''F01'' then m.ISSUER else m.FINANCIER end org_code 
FROM  FIN_PRODUCT m
INNER JOIN  FIN_PRODUCT_TYPE fpt ON  m.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0
AND (  (fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR  ( fpt.TYPE_8 =''F01''  AND fpt.TYPE_6 =''B18'')))

select a.FINPROD_ID RKEY,CASE WHEN CORORG IS NULL THEN 0 ELSE 1 END RVALUE from  temp a
left join (SELECT ORG_NO,COUNT(COR_ORGID) AS CORORG FROM INF_ORG_CORRELATION WHERE ORG_NO <> COR_ORGID GROUP BY ORG_NO) b ON a.org_code=b.ORG_NO', 'assetCode', 'N', 'jjpei', '00000', sysdate, 'jjpei', sysdate);

