INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FHMB', '04', 'SQL', 'SELECT
	nvl(SUM(nvl(PTL_SEC_VALUTION1.DSC_COST_AMT, 0)),0) AS CST,
	nvl(SUM(nvl(PTL_SEC_VALUTION1.SHARE_AMT, 0)),0) AS QTY,
	nvl(SUM(nvl(PTL_SEC_VALUTION1.TDY_FLOAT_INGPL, 0) + nvl(PTL_SEC_VALUTION1.DSC_COST_AMT, 0)+nvl(PTL_SEC_VALUTION1.TDY_INTINCEXP, 0)+nvl(PTL_SEC_VALUTION1.DELAY_PAY_AMT, 0)),0) AS MKT,
	FIN_PRODUCT_TYPE1.TYPE_4 windAssetType,
	FIN_PRODUCT_TYPE1.TYPE_5 windAssetType2,
	FIN_PRODUCT_TYPE1.TYPE_6 assetType,
	FIN_PRODUCT_TYPE1.TYPE_7 assetType2,
	FIN_PRODUCT_ADD1.INVEST_NATURE investNature,
	REP_ASSET_DEPT1.REP_ASSET_TYPE deptType,
	REP_ASSET_DEPT1.REP_ASSET_TYPE deptType2,
	PTL_SEC_VALUTION1.FINPROD_ID finprodId,
	FIN_PRODUCT1.ISSUER issuer,
	MST_CUSTOMER_INFO1.INDUSTRY industry,
	MST_CUSTOMER_INFO1.INDUSTRY2 industry2,
	ZXRATING1.GRADE_RESULT bondGradeType,
	ZTRATING1.GRADE_RESULT bodyGradeType,
	PTL_SEC_VALUTION1.PORTFOLIO_ID portfolioId,
	FIN_PRODUCT1.MDATE mdate
	FROM PTL_SEC_VALUTION PTL_SEC_VALUTION1
	LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON PTL_SEC_VALUTION1.FINPROD_ID = FIN_PRODUCT1.FINPROD_ID
	LEFT JOIN (SELECT s1.*,s2.INDUSTRY,s2.INDUSTRY2 FROM MST_CUSTOMER_INFO s1 INNER JOIN MST_CUSTOMER_INFO_ADD s2 ON s1.CUSTOMER_ID=s2.CUSTOMER_ID) MST_CUSTOMER_INFO1 ON FIN_PRODUCT1.ISSUER = MST_CUSTOMER_INFO1.CUSTOMER_ID
	LEFT JOIN FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE1 ON PTL_SEC_VALUTION1.FINPROD_ID = FIN_PRODUCT_TYPE1.FINPROD_ID
	LEFT JOIN FIN_PRODUCT_ADD FIN_PRODUCT_ADD1 ON FIN_PRODUCT_ADD1.FINPROD_ID = PTL_SEC_VALUTION1.FINPROD_ID
	LEFT JOIN REP_ASSET_DEPT REP_ASSET_DEPT1 ON PTL_SEC_VALUTION1.FINPROD_ID = REP_ASSET_DEPT1.REP_FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''02'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZXRATING1 ON ZXRATING1.O_CODE = PTL_SEC_VALUTION1.FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_DATE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''01'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZTRATING1 ON ZTRATING1.O_CODE = PTL_SEC_VALUTION1.FINPROD_ID
	WHERE  PTL_SEC_VALUTION1.PORTFOLIO_ID in ${portfolioCode} and PTL_SEC_VALUTION1.CDATE =date''${valDate}''-1 
	GROUP BY	PTL_SEC_VALUTION1.PORTFOLIO_ID,FIN_PRODUCT_TYPE1.TYPE_4,FIN_PRODUCT_TYPE1.TYPE_5,FIN_PRODUCT_TYPE1.TYPE_6,FIN_PRODUCT_TYPE1.TYPE_7,FIN_PRODUCT_ADD1.INVEST_NATURE, REP_ASSET_DEPT1.REP_ASSET_TYPE,	PTL_SEC_VALUTION1.FINPROD_ID,FIN_PRODUCT1.ISSUER,MST_CUSTOMER_INFO1.INDUSTRY,MST_CUSTOMER_INFO1.INDUSTRY2,ZXRATING1.GRADE_RESULT,ZTRATING1.GRADE_RESULT,FIN_PRODUCT1.MDATE
	  union all ', 'portfolioCode', 'N', 'admin', '001', sysdate, 'admin', sysdate);
