	WHERE PTL_SEC_VALUTION1.CDATE = DATE ''${valDate}''-1 
	GROUP BY	PTL_SEC_VALUTION1.PORTFOLIO_ID,FIN_PRODUCT_TYPE1.TYPE_4,FIN_PRODUCT_TYPE1.TYPE_5,FIN_PRODUCT_TYPE1.TYPE_6,FIN_PRODUCT_TYPE1.TYPE_7,FIN_PRODUCT_ADD1.INVEST_NATURE, REP_ASSET_DEPT1.REP_ASSET_TYPE,	PTL_SEC_VALUTION1.FINPROD_ID,FIN_PRODUCT1.ISSUER,MST_CUSTOMER_INFO1.INDUSTRY,MST_CUSTOMER_INFO1.INDUSTRY2,ZXRATING1.GRADE_RESULT,ZTRATING1.GRADE_RESULT,FIN_PRODUCT1.MDATE
	  union all ', 'portfolioCode', 'N', 'admin', '001', sysdate, 'admin', sysdate);
