INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('MOTHERDZTDQTUZDWETE', '04', 'SQL', 'WITH BOND AS (		
  SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno		
		FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
)		
SELECT DISTINCT RVALUE,RKEY,RKEYCN FROM (		
	SELECT nvl(t2.ISSUE_AMT,0)*BOND.PRICE/100 AS RVALUE,	
	T2.FINPROD_ID RKEY,t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''-1	
UNION ALL		
	SELECT nvl(t2.ISSUE_AMT,0)*BOND.PRICE/100 AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM TRD_PRODUCT_DEAL t1	
	INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON t1.TRADE_ID =n1.TRADE_ID	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
	WHERE n1.PORTFOLIO_ID IN ${portfolioCode} AND t1.TRADE_DATE=date''${valDate}''	
UNION ALL		
	SELECT nvl(t2.ISSUE_AMT,0)*BOND.PRICE/100 AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM WFL_TRD_PRODUCT_DEAL_ADD t1	
	inner join WFL_TRD_PRODUCT_DEAL n on t1.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''	
	INNER JOIN FIN_PRODUCT t2 ON n.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE=date''${valDate}''	
) S1', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('XJGM', '02', 'SQL', '  select m.PORTFOLIO_ID RKEY,nvl(sum(n.AMOUNT),0) as  RVALUE  from PTL_PORTFOLIO m 	
  LEFT JOIN PTL_CASH_POSITION n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND  n.HODING_TYPE=''03'' AND n.CDATE =date''${valDate}''-1	
  where  m.PORTFOLIO_TYPE IN (''01'',''02'') AND m.MDATE>date''${valDate}''  group by m.PORTFOLIO_ID	
union all	
   select t.PTL_BAG_ID as RKEY,	
   ( select nvl(sum(AMOUNT),0) as  TRADE_AMT from PTL_CASH_POSITION	
	where  HODING_TYPE=''03'' and CDATE =date''${valDate}''-1  AND 
	PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)
   )	
   from RSK_PORTFOLIO_PACKAGE t	', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('XJGM', '03', 'SQL', '  select m.PORTFOLIO_ID RKEY,nvl(sum(n.AMOUNT),0) as  RVALUE  from PTL_PORTFOLIO m 	
  LEFT JOIN PTL_CASH_POSITION n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND  n.HODING_TYPE=''03'' AND n.CDATE =date''${valDate}''-1	
  where  m.PORTFOLIO_TYPE IN (''01'',''02'') AND m.MDATE>date''${valDate}''  group by m.PORTFOLIO_ID	
union all	
   select t.PTL_BAG_ID as RKEY,	
   ( select nvl(sum(AMOUNT),0) as  TRADE_AMT from PTL_CASH_POSITION	
	where  HODING_TYPE=''03'' and CDATE =date''${valDate}''-1  AND 
	PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)
   )	
   from RSK_PORTFOLIO_PACKAGE t	', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('ZCSYQX', '05', 'SQL', 'SELECT (nvl(sum((TRADE_AMT)*(LAST_PERIOD)),0)) AS lastPeriod FROM (select 				
	A1.FINPROD_ID, 			
	A1.TRADE_AMT, 			
	A1.MDATE, 			
	CASE WHEN A1.FINPROD_TYPE =''F01'' THEN 			
	( 			
	 	select CASE WHEN nvl(sum(B1.LAST_PERIOD),0)=0 THEN (((A1.mdate)-(date''${valDate}''))) ELSE (nvl(sum(B1.LAST_PERIOD),0))*365 END LAST_PERIOD from  MST_BOND_VALUATION_INFO B1 		
	    inner join 			
	    (select to_char(max(VALUE_DATE),''yyyy-MM-dd'') as VALUE_DATE,SEC_ID from MST_BOND_VALUATION_INFO where VALUE_DATE<=date''${valDate}'' group by sec_id) B2 			
	    on B1.SEC_ID=B2.SEC_ID and B1.VALUE_DATE=B2.VALUE_DATE WHERE B1.SEC_ID=A1.FINPROD_ID 			
	) 			
	WHEN (A1.FINPROD_TYPE =''F06'' OR A1.FINPROD_TYPE =''XJ'') THEN (1) 			
	WHEN a1.FINPROD_ID =a1.PORTFOLIO_ID 			
	THEN (1) 			
    ELSE ((A1.mdate)-(date''${valDate}'')) END LAST_PERIOD 				
from 				
( 				
  select NULL AS FINPROD_ID,NULL AS PORTFOLIO_ID,nvl(sum(AMOUNT),0) as  TRADE_AMT,''XJ'' AS FINPROD_TYPE,NULL AS MDATE   from PTL_CASH_POSITION 				
 	 where  PORTFOLIO_ID in ${portfolioCode} and HODING_TYPE=''03'' and CDATE =date''${valDate}'' 			
    UNION ALL 				
	select 			
	t1.FINPROD_ID,t1.PORTFOLIO_ID,nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0) as TRADE_AMT,t2.FINPROD_TYPE2,t2.MDATE 			
	from PTL_SEC_VALUTION t1 			
	 inner join FIN_PRODUCT t2	on t1.FINPROD_ID = t2.FINPROD_ID 		
	where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}'' 			
    UNION ALL 				
    select 				
	t1.FINPROD_ID,t1.PORTFOLIO_ID,nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP, 0) as TRADE_AMT,t3.FINPROD_TYPE2,t3.MDATE 			
	from PTL_SEC_VALUTION t1 			
	inner join FIN_TRADE_PRODUCT t3	 on t1.FINPROD_ID = t3.FINPROD_ID AND t3.BRANCH=0		
	where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}'' 			
	and  t3.FINPROD_TYPE2 not in (''F02'', ''F04'',''F08'', ''F25'') 			
) A1 				
)', 'assetCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('XJGM', '01', 'SQL', '  select m.PORTFOLIO_ID RKEY,nvl(sum(n.AMOUNT),0) as  RVALUE  from PTL_PORTFOLIO m 	
  LEFT JOIN PTL_CASH_POSITION n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND  n.HODING_TYPE=''03'' AND n.CDATE =date''${valDate}''-1	
  where  m.PORTFOLIO_TYPE IN (''01'',''02'') AND m.MDATE>date''${valDate}''  group by m.PORTFOLIO_ID	
union all	
   select t.PTL_BAG_ID as RKEY,	
   ( select nvl(sum(AMOUNT),0) as  TRADE_AMT from PTL_CASH_POSITION	
	where  HODING_TYPE=''03'' and CDATE =date''${valDate}''-1  AND 
	PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)
   )	
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);
