	inner join INF_ORG_CORRELATION b on a.org_code = b.ORG_NO) g on f.org_code = g.org_code_union and f.FINPROD_ID=g.FINPROD_ID and f.FINPROD_TYPE2 = g.FINPROD_TYPE2	
left join MST_CUSTOMER_INFO t3 on  f.org_code=t3.CUSTOMER_ID		
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE =date''${valDate}'' group by PORTFOLIO_ID ,g.org_code,T3.CUSTOMER_NAME		
) targetData		
group by targetData.ASSETCODE, targetData.ASSETNAME', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);

-------FHMB指标参数明细更新

    update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' SELECT
	nvl(SUM(nvl(PTL_SEC_VALUTION2.DSC_COST_AMT, 0)),0) AS CST,
	nvl(SUM(nvl(PTL_SEC_VALUTION2.SHARE_AMT, 0)),0) AS QTY,
	nvl(SUM(nvl(PTL_SEC_VALUTION2.TDY_FLOAT_INGPL, 0) + nvl(PTL_SEC_VALUTION2.DSC_COST_AMT, 0)+nvl(PTL_SEC_VALUTION2.TDY_INTINCEXP, 0)+nvl(PTL_SEC_VALUTION2.DELAY_PAY_AMT, 0)),0) AS MKT,
	FIN_PRODUCT_TYPE2.TYPE_4 windAssetType,
	FIN_PRODUCT_TYPE2.TYPE_5 windAssetType2,
	FIN_PRODUCT_TYPE2.TYPE_6 assetType,
	FIN_PRODUCT_TYPE2.TYPE_7 assetType2,
	FIN_PRODUCT_ADD2.INVEST_NATURE investNature,
