	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_DATE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''01'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZTRATING2 ON ZTRATING2.O_CODE = PTL_SEC_VALUTION2.FINPROD_ID
