	update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' SELECT
	nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T01'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T07'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T17'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T04'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T36'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T03'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T12'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T09'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T10'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T19'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T02'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T13'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T14'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T11'',TRD_PRODUCT_DEAL.PRIN_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T05'',TRD_PRODUCT_DEAL.PRIN_AMT)),0) as  CST,
	nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T01'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T07'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T17'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T04'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
