	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T03'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T12'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T09'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T10'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T19'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T02'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T13'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T14'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T11'',TRD_PRODUCT_DEAL.TRADE_AMT)),0)
	-nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T05'',TRD_PRODUCT_DEAL.TRADE_AMT)),0) as  MKT,
	nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T01'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T07'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
	+nvl(sum(decode(TRD_PRODUCT_DEAL.PS,''T17'',TRD_PRODUCT_DEAL.SHARE_AMT)),0)
